import{_ as a,o as t,c as i,a3 as l}from"./chunks/framework.BlfGB29P.js";const _=JSON.parse('{"title":"上下文与 Middleware","description":"讲解 Agent 每一步获得什么信息，以及应用如何在运行生命周期中实施动态控制。","frontmatter":{"title":"上下文与 Middleware","description":"讲解 Agent 每一步获得什么信息，以及应用如何在运行生命周期中实施动态控制。"},"headers":[],"relativePath":"py-agent/agent/context-middleware/index.md","filePath":"py-agent/agent/context-middleware/index.md","lastUpdated":1785314595000}'),n={name:"py-agent/agent/context-middleware/index.md"};function r(d,e,o,c,s,p){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="上下文与-middleware" tabindex="-1">上下文与 Middleware <a class="header-anchor" href="#上下文与-middleware" aria-label="Permalink to &quot;上下文与 Middleware&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>本分组解决 Agent 开发中最容易混淆的两类问题：上下文工程决定每一步获得什么信息，Middleware 决定在模型与工具生命周期中怎样观察、修改和限制执行。</p><h2 id="_1-学习目标" tabindex="-1">1. 学习目标 <a class="header-anchor" href="#_1-学习目标" aria-label="Permalink to &quot;1. 学习目标&quot;">​</a></h2><p>完成后，你应该能够：</p><ol><li>区分广义上下文与模型上下文；</li><li>按生命周期放置 State、Context、Store 和业务数据；</li><li>使用 Runtime Context 注入受信任身份和依赖；</li><li>区分节点钩子和模型、工具包装钩子；</li><li>实现动态 Prompt、模型和工具选择；</li><li>在输入、模型、工具和运行预算四个边界设置 Guardrails。</li></ol><h2 id="_2-文章顺序" tabindex="-1">2. 文章顺序 <a class="header-anchor" href="#_2-文章顺序" aria-label="Permalink to &quot;2. 文章顺序&quot;">​</a></h2><ol><li><a href="/py-agent/agent/context-middleware/context-engineering">上下文工程</a>：信息选择、转换、预算、写回和隔离。</li><li><a href="/py-agent/agent/context-middleware/runtime-context">Runtime Context</a>：请求级受信任数据与依赖注入。</li><li><a href="/py-agent/agent/context-middleware/middleware">Middleware</a>：钩子生命周期、顺序、状态与错误语义。</li><li><a href="/py-agent/agent/context-middleware/dynamic-control-guardrails">动态控制与 Guardrails</a>：将上下文与 Middleware 用于运行策略。</li></ol><h2 id="_3-分组边界" tabindex="-1">3. 分组边界 <a class="header-anchor" href="#_3-分组边界" aria-label="Permalink to &quot;3. 分组边界&quot;">​</a></h2><p>本组讲单 Agent 的上下文与控制面。RAG、长期记忆、跨节点工作流和多 Agent 上下文隔离在后续模块继续展开。</p>',10)])])}const h=a(n,[["render",r]]);export{_ as __pageData,h as default};
